<template>
	<view class="meet-page">
		<view class="static-panel">
			<view class="fixed-hero" :style="{ paddingTop: headerTop + 'px' }">
				<view class="home-hero-aura aura-pink"></view>
				<view class="home-hero-aura aura-purple"></view>
				<view class="topbar" :style="{ height: searchBoxHeight + 'px', paddingRight: menuButtonSafeRight + 'px' }">
					<view class="mail-entry" :style="{ width: searchBoxHeight + 'px', height: searchBoxHeight + 'px' }" @click="goMailbox">
						<image class="mail-entry-icon" src="/static/img/xinxiang.png" mode="aspectFit" />
						<text v-if="mailUnreadCount" class="mail-entry-badge">{{ mailUnreadText }}</text>
					</view>
					<view class="search-box" :style="{ height: searchBoxHeight + 'px' }" @click="goSearch">
						<text class="search-icon"></text>
						<text class="search-placeholder">搜索动态、话题或用户</text>
					</view>
				</view>

				<view class="feature-grid">
					<view
						class="feature-card feature-card-main"
						hover-class="feature-card-hover"
						hover-stay-time="80"
						@click="pickBottle"
					>
						<view class="card-decor">
							<view class="decor-blob decor-blob-1"></view>
							<view class="decor-blob decor-blob-2"></view>
							<view class="decor-blob decor-blob-3"></view>
							<view class="decor-stars">
								<text class="decor-star">✦</text>
								<text class="decor-star">✦</text>
								<text class="decor-star">✦</text>
							</view>
							<view class="feature-icon feature-icon-note">
								<view class="note-shape"></view>
								<view class="note-fold"></view>
								<view class="note-line note-line-1"></view>
								<view class="note-line note-line-2"></view>
								<view class="note-line note-line-3"></view>
							</view>
						</view>
						<view class="card-content">
							<view class="card-kicker card-kicker-spark">
								<text class="kicker-spark-icon">✦</text>
								<text>每次都有新遇见</text>
							</view>
							<view class="card-title" style="font-size: 46rpx;">捡纸条</view>
							<view class="card-desc">读一段同频心事</view>
							<view class="card-button" @click.stop="pickBottle">
								<text class="card-button-text">去捡起一张</text>
								<text class="card-arrow">›</text>
							</view>
						</view>
					</view>

					<view
						class="feature-card feature-card-invite"
						hover-class="feature-card-hover"
						hover-stay-time="80"
						@click="goInviteFriends"
					>
						<view class="ticket-notch"></view>
						<view class="ticket-perforation"></view>
						<view class="card-content card-content-invite">
							<view class="invite-ticket-kicker">
								<text class="invite-kicker-dot"></text>
								<text>同行邀请</text>
							</view>
							<view class="card-title small card-title-invite">邀TA同行</view>
							<view class="card-desc small">把同频分享给朋友</view>
						</view>
						<view class="ticket-stub">
							<text class="ticket-stub-label">INV.</text>
							<text class="ticket-stub-number">001</text>
						</view>
					</view>

					<view
						class="feature-card feature-card-write"
						hover-class="feature-card-hover"
						hover-stay-time="80"
						@click="goWriteLetter()"
					>
						<view class="card-decor">
							<view class="decor-blob decor-blob-1"></view>
							<view class="decor-blob decor-blob-2"></view>
							<view class="decor-stars">
								<text class="decor-star">✦</text>
								<text class="decor-star">✦</text>
							</view>
							<view class="feature-icon feature-icon-pen">
								<text class="pen-glyph">✎</text>
								<view class="pen-spark pen-spark-1"></view>
								<view class="pen-spark pen-spark-2"></view>
							</view>
						</view>
						<view class="card-content">
							<view class="card-title small card-title-underline">写纸条</view>
							<view class="card-desc small">把此刻的心情留下</view>
							<view class="card-button small warm" @click.stop="goWriteLetter()">
								<text class="card-button-text">写一张</text>
								<text class="card-arrow">›</text>
							</view>
						</view>
					</view>
				</view>
			</view>

			<view class="fixed-list-header">
				<view class="section-title-row compact">
					<view class="people-tabs">
						<text
							v-for="tab in peopleTabs"
							:key="tab.value"
							class="people-tab"
							:class="{ active: activePeopleTab === tab.value }"
							@click="switchPeopleTab(tab.value)"
						>
							{{ tab.label }}
						</text>
					</view>
					<text class="refresh-link" @click="refreshPeopleList">换一批</text>
				</view>
			</view>
		</view>

		<scroll-view
			class="meet-scroll"
			scroll-y
			enhanced
			:show-scrollbar="false"
			:lower-threshold="80"
			refresher-enabled
			refresher-background="#f8f6fb"
			refresher-default-style="none"
			:refresher-threshold="30"
			:refresher-max-drag-distance="42"
			:refresher-triggered="peopleRefreshing"
			@refresherrefresh="refreshPeopleList"
			@scrolltolower="loadMorePeople"
		>
			<view slot="refresher" class="people-refresh-slot">
				<text class="refresh-icon">↻</text>
				<text class="refresh-text">{{ peopleRefreshing ? '正在更新同频推荐' : '下拉看看新的同频' }}</text>
				<view class="load-dots">
					<text></text>
					<text></text>
					<text></text>
				</view>
			</view>
			<view class="page-shell">
				<view class="people-section recommend-section">
					<view class="recommend-list">
						<view
							v-for="user in displayUsers"
							:key="user.id"
							class="recommend-card"
							@click="goUser(user.id)"
						>
							<view class="recommend-head">
								<view class="recommend-avatar-shell">
									<image class="recommend-avatar" :src="user.avatar" mode="aspectFill" />
									<view v-if="user.online" class="recommend-online-dot"></view>
								</view>
								<view class="recommend-profile">
									<view class="recommend-name-row">
										<VipName class="recommend-name" :name="user.name" :is-member="user.isMember" />
										<text class="recommend-match">{{ user.match }}%</text>
									</view>
									<view class="recommend-meta-row">
										<image class="recommend-gender-icon" :src="getGenderIcon(user.gender)" mode="aspectFit" />
										<text class="recommend-meta-dot"></text>
										<text>{{ user.age }}岁</text>
										<text class="recommend-meta-dot"></text>
										<text>{{ user.city }}</text>
									</view>
									<text class="recommend-bio">{{ user.bio }}</text>
									<text class="recommend-reason">同频：{{ user.reason }}</text>
								</view>
							</view>
						</view>
					</view>
					<view class="people-load-state">
						<text class="load-text">
							{{ peopleLoadingMore ? '正在加载更多同频' : (peopleHasMore ? '上拉发现更多同频' : '暂时没有更多同频了') }}
						</text>
						<view v-if="peopleLoadingMore || peopleHasMore" class="load-dots">
							<text></text>
							<text></text>
							<text></text>
						</view>
					</view>
				</view>

				<!-- <view class="bottom-safe"></view> -->
			</view>
		</scroll-view>

		<view v-if="noteOverlayVisible" class="note-overlay" @touchmove.stop.prevent>
			<view class="note-soft-mask"></view>
			<view class="note-bg-grid"></view>
			<view class="note-glow note-glow-pink"></view>
			<view class="note-glow note-glow-blue"></view>
			<view class="note-particle-field">
				<text v-for="item in noteParticles" :key="item" class="note-particle"></text>
			</view>

			<view v-if="noteStage === 'searching'" class="note-pick-scene">
				<view class="light-beam-loader">
					<view class="beam beam-pink beam-fast"></view>
					<view class="beam beam-purple beam-medium"></view>
					<view class="beam beam-rose beam-slow"></view>
					<view class="beam beam-blue beam-reverse"></view>
					<view class="beam-spark spark-left"></view>
					<view class="beam-spark spark-right"></view>
					<view class="beam-core"></view>
				</view>
				<text class="note-loading-title">正在捡起一张小纸条</text>
				<text class="note-loading-sub">它正在从同频的人那里靠近你</text>
				<view class="loading-dots">
					<text></text>
					<text></text>
					<text></text>
				</view>
			</view>

			<view v-else-if="currentNote" class="note-result-scene" :class="{ replying: noteReplyVisible }">
				<view class="note-sheet-wrap">
					<view class="note-sheet-shadow"></view>
					<view class="note-sheet">
						<view class="note-tape tape-left"></view>
						<view class="note-tape tape-right"></view>
						<view class="note-sheet-head">
							<view class="note-author">
								<image class="note-author-avatar" :src="currentNote.avatar" mode="aspectFill" />
								<view class="note-author-info">
									<VipName class="note-author-name" :name="currentNote.authorName" :is-member="currentNote.authorIsMember" />
									<text class="note-author-meta">{{ currentNote.gender }} · {{ currentNote.age }}岁 · {{ currentNote.city }}</text>
								</view>
							</view>
							<text class="note-match">{{ currentNote.match }}%</text>
						</view>
						<view class="note-divider"></view>
						<text class="note-label">TA 的小纸条</text>
						<text v-if="currentNote.type === 'text'" class="note-content">{{ currentNote.content }}</text>
						<image v-else-if="currentNote.type === 'image' && currentNote.image" class="note-image-content" :src="currentNote.image.url" mode="aspectFill" @click="previewPickedNoteImage" />
						<view v-else-if="currentNote.type === 'voice' && currentNote.audio" class="note-audio-content">
							<text class="note-audio-icon">♪</text>
							<text>{{ currentNote.audio.duration ? `${currentNote.audio.duration}s` : '语音纸条' }}</text>
						</view>
						<view class="note-footer-row">
							<text class="note-source">同频：{{ currentNote.reason }}</text>
						</view>
						<view v-if="noteReplyVisible" class="note-reply-box">
								<textarea
									v-model="noteReplyContent"
									class="note-reply-input"
									placeholder="给这张小纸条写一句回复..."
									placeholder-class="note-reply-placeholder"
									maxlength="300"
									:fixed="true"
									cursor-spacing="24"
									auto-height
								/>
								<view class="note-reply-foot">
									<text>{{ noteReplyContent.length }} / 300</text>
									<view
										class="note-reply-submit"
										:class="{ disabled: !canSubmitNoteReply }"
										@click="submitNoteReply"
									>
										{{ noteReplySubmitting ? '发送中...' : '送出回复' }}
									</view>
								</view>
							</view>
					</view>
				</view>
				<view class="note-actions">
					<view class="note-action ghost" @click="closeNoteOverlay">收起</view>
					<view class="note-action soft" @click="toggleNoteReply">
						{{ noteReplyVisible ? '收起回复' : '回复纸条' }}
					</view>
					<view class="note-action primary" @click="goNoteAuthor">看看 TA</view>
				</view>
			</view>
		</view>

		<view v-if="writeOverlayVisible" class="write-note-overlay">
			<view class="write-note-mask" @click="closeWriteOverlay"></view>
			<view class="write-note-dialog">
				<view class="write-note-tape tape-left"></view>
				<view class="write-note-tape tape-right"></view>
				<view class="write-note-head">
					<view>
						<text class="write-note-title">写一张小纸条</text>
						<text class="write-note-sub">留给同频的人，也留给此刻的自己</text>
					</view>
					<view class="write-note-close" @click="closeWriteOverlay">×</view>
				</view>
				<scroll-view class="write-note-body" scroll-y enhanced :show-scrollbar="false" @touchmove.stop>
					<view class="write-type-switch">
						<view
							v-for="item in writeTypeOptions"
							:key="item.value"
							class="write-type-item"
							:class="{ active: writeForm.type === item.value }"
							@click="switchWriteType(item.value)"
						>
							<text>{{ item.label }}</text>
						</view>
					</view>
					<textarea
						v-if="writeForm.type === 'text'"
						v-model="writeForm.content"
						class="write-note-input"
						placeholder="把此刻的心情写下来..."
						placeholder-class="write-note-placeholder"
						maxlength="600"
						auto-height
					/>
					<view v-if="writeForm.type === 'image'" class="write-note-image-panel">
						<view v-if="writeForm.images.length" class="write-note-image-grid">
							<view v-for="(item, index) in writeForm.images" :key="item.url || index" class="write-note-image">
								<image class="write-note-thumb" :src="item.url" mode="aspectFill" @click="previewWriteImage(index)" />
								<view class="write-note-image-remove" @click.stop="removeWriteImage(index)">×</view>
							</view>
						</view>
						<view v-if="!writeForm.images.length" class="write-pick-panel image-pick" :class="{ disabled: writeUploading }" @click="chooseWriteImage">
							<text class="write-pick-icon">＋</text>
							<text>{{ writeUploading ? '图片上传中' : '选择图片' }}</text>
						</view>
					</view>
					<view v-if="writeForm.type === 'voice'" class="write-voice-mode">
						<view v-if="!writeForm.audio || writeRecording" class="write-record-panel" :class="{ active: writeRecording }" @click="toggleWriteRecording">
							<view class="write-record-button">
								<view v-if="writeRecording" class="write-stop-icon"></view>
								<view v-else class="write-mic-icon"><view></view></view>
							</view>
							<view class="write-record-copy">
								<text class="write-record-title">{{ writeRecording ? `录音中 ${formatRecordClock(writeRecordDuration)}` : '开始录音' }}</text>
								<text class="write-record-sub">{{ writeRecording ? '点击结束' : '最长 60 秒' }}</text>
							</view>
						</view>
						<view v-else class="write-voice-card" :class="{ playing: writeVoicePlaying, loading: writeVoiceLoading }">
							<view class="write-voice-main" @click="playWriteVoice">
								<view class="write-voice-play">
									<view v-if="writeVoicePlaying" class="write-play-stop"></view>
									<view v-else class="write-play-triangle"></view>
								</view>
								<view class="write-voice-copy">
									<text class="write-voice-state">{{ writeVoicePlaying ? '播放中' : (writeVoiceLoading ? '正在加载' : '播放录音') }}</text>
									<view class="write-voice-wave">
										<text></text><text></text><text></text><text></text><text></text>
									</view>
								</view>
								<text class="write-voice-time">{{ formatVoiceDuration(writeForm.audio.duration) }}</text>
							</view>
							<view class="write-voice-actions">
								<view class="write-voice-retry" @click="toggleWriteRecording">重录</view>
								<view class="write-voice-remove" @click="removeWriteVoice">×</view>
							</view>
						</view>
					</view>
					<view v-if="writeForm.type === 'text'" class="write-note-tools">
						<text class="write-note-count">{{ writeForm.content.length }} / 600</text>
					</view>
				</scroll-view>
				<view class="write-note-actions">
					<view class="write-note-action ghost" @click="closeWriteOverlay">取消</view>
					<view class="write-note-action primary" :class="{ disabled: !canSubmitWriteNote }" @click="submitWriteNote">
						<text>{{ writeSubmitting ? '发布中...' : '放飞小纸条' }}</text>
					</view>
				</view>
			</view>
		</view>

		<SoftToast
			:visible="softToast.visible"
			:message="softToast.message"
			:type="softToast.type"
		/>
		<SoftDialog
			:visible="softDialog.visible"
			:title="softDialog.title"
			:content="softDialog.content"
			:confirm-text="softDialog.confirmText"
			:cancel-text="softDialog.cancelText"
			:show-cancel="softDialog.showCancel"
			:mask-closable="softDialog.maskClosable"
			@confirm="handleSoftDialogConfirm"
			@cancel="handleSoftDialogCancel"
		/>
		<SuccessFlyModal
			:visible="successFly.visible"
			:label="successFly.label"
			:sublabel="successFly.sublabel"
			@close="handleSuccessFlyClose"
		/>
		<HomeAnnouncement
			:visible="homeAnnouncementVisible"
			:title="homeAnnouncement.title"
			:content="homeAnnouncement.content"
			@close="acknowledgeHomeAnnouncement"
			@confirm="acknowledgeHomeAnnouncement"
		/>
	</view>
</template>

<script>
import { createNote, pickNote, replyNote } from '../../api/note';
import { fetchNotificationSummary } from '../../api/notification';
import { fetchMeetUsers } from '../../api/user';
import { fetchDiamonds } from '../../api/diamond';
import { DEFAULT_AVATAR_URL } from '../../config';
import { setPendingInviter } from '../../utils/auth';
import { getAppBootstrapConfig, loadAppMode } from '../../utils/appMode';
import { isChatUserOnline, sendChatSocketEvent, subscribeChatEvents } from '../../utils/chatSocket';
import { showRequestError } from '../../utils/feedback';
import * as profileGuard from '../../utils/profileGuard';
import { uploadAudio, uploadImage } from '../../utils/request';
import VipName from '../../components/VipName.vue';
import SoftToast from '../../components/SoftToast.vue';
import SoftDialog from '../../components/SoftDialog.vue';
import SuccessFlyModal from '../../components/SuccessFlyModal.vue';
import HomeAnnouncement from '../../components/HomeAnnouncement.vue';

const HOME_ANNOUNCEMENT_STORAGE_KEY = 'meet-home-announcement-last-seen-date';

export default {
	components: { VipName, SoftToast, SoftDialog, SuccessFlyModal, HomeAnnouncement },
	data() {
		return {
			homeAnnouncementVisible: false,
			homeAnnouncementTimer: null,
			homeAnnouncement: {
				enabled: false,
				title: '',
				content: ''
			},
			noteOverlayVisible: false,
			noteStage: 'idle',
			currentNote: null,
			notePickTimer: null,
			noteReplyVisible: false,
			noteReplyContent: '',
			noteReplySubmitting: false,
			noteParticles: Array.from({ length: 18 }, (_, index) => index + 1),
			statusBarHeight: 44,
			headerTop: 44,
			menuButtonHeight: 32,
			searchBoxHeight: 40,
			menuButtonSafeRight: 88,
			mailUnreadCount: 0,
			activePeopleTab: 'recommend',
			diamondBalance: 0,
			peopleTabs: [
				{ label: '推荐', value: 'recommend' },
				{ label: '热门', value: 'hot' }
			],
			peoplePageSize: 6,
			peopleRefreshing: false,
			peopleLoadingMore: false,
			peopleLoading: false,
			realtimeUnsubscribe: null,
			peoplePagination: {
				recommend: 1,
				hot: 1
			},
			meetUsers: {
				recommend: [],
				hot: []
			},
			writeOverlayVisible: false,
			writeSubmitting: false,
			writeUploading: false,
			writeRecording: false,
			writeVoicePlaying: false,
			writeVoiceLoading: false,
			writeRecorder: null,
			writeRecorderStopHandler: null,
			writeRecorderErrorHandler: null,
			writeInnerAudio: null,
			writeRecordStartAt: 0,
			writeRecordDuration: 0,
			writeRecordTimer: null,
			writeDiscardRecording: false,
			writeTypeOptions: [
				{ label: '文字', value: 'text' },
				{ label: '图片', value: 'image' },
				{ label: '语音', value: 'voice' }
			],
			writeForm: {
				type: 'text',
				content: '',
				images: [],
				audio: null
			},
			softToast: {
				visible: false,
				message: '',
				type: 'success'
			},
			softToastTimer: null,
			softDialog: {
				visible: false,
				title: '',
				content: '',
				confirmText: '确定',
				cancelText: '取消',
				showCancel: true,
				maskClosable: true,
				onConfirm: null,
				onCancel: null
			},
			successFly: {
				visible: false,
				label: '',
				sublabel: ''
			},
			notePool: [
				{
					id: 'n1',
					authorId: 'u1',
					authorName: '夏日纸条',
					avatar: DEFAULT_AVATAR_URL,
					gender: '女',
					age: 24,
					city: '杭州',
					match: 92,
					content: '今天散步的时候突然觉得，能把一句没说出口的话好好放下，也算是一种很小的勇敢。',
					reason: '都常在夜里写下真实想法',
					time: '刚刚'
				},
				{
					id: 'n2',
					authorId: 'u2',
					authorName: '海盐苏打',
					avatar: DEFAULT_AVATAR_URL,
					gender: '女',
					age: 27,
					city: '厦门',
					match: 88,
					content: '有时候很想有人问一句，今天有没有好一点。不用帮我解决，只要听见就够了。',
					reason: '最近也在写睡不着的时刻',
					time: '12 分钟前'
				},
				{
					id: 'n3',
					authorId: 'u5',
					authorName: '月亮邮差',
					avatar: DEFAULT_AVATAR_URL,
					gender: '女',
					age: 22,
					city: '苏州',
					match: 86,
					content: '我喜欢把情绪写短一点，好像字少了，心事也会轻一点。',
					reason: '都喜欢把情绪写成很短的句子',
					time: '半小时前'
				},
				{
					id: 'n4',
					authorId: 'u8',
					authorName: '没睡醒的云',
					avatar: DEFAULT_AVATAR_URL,
					gender: '女',
					age: 25,
					city: '长沙',
					match: 84,
					content: '今天的愿望很小：想被温柔对待，也想有力气温柔地对待别人。',
					reason: '都在写没说出口的小愿望',
					time: '1 小时前'
				},
				{
					id: 'n5',
