	computed: {
		currentPeopleSource() {
			const users = this.meetUsers[this.activePeopleTab] || [];
			return users
				.map((user, index) => ({ user, index }))
				.sort((left, right) => (
					Number(right.user.online) - Number(left.user.online) || left.index - right.index
				))
				.map((item) => item.user);
		},
		currentPeoplePage() {
			return this.peoplePagination[this.activePeopleTab] || 1;
		},
		displayUsers() {
			return this.currentPeopleSource.slice(0, this.currentPeoplePage * this.peoplePageSize);
		},
		peopleHasMore() {
			return this.displayUsers.length < this.currentPeopleSource.length;
		},
		canSubmitWriteNote() {
			const type = this.writeForm.type || 'text';
			const hasContent = type === 'text'
				? Boolean(this.writeForm.content.trim())
				: type === 'image'
					? this.writeForm.images.length > 0
					: Boolean(this.writeForm.audio);
			return !this.writeSubmitting &&
				!this.writeUploading &&
				!this.writeRecording &&
				hasContent;
		},
		canSubmitNoteReply() {
			return !this.noteReplySubmitting && Boolean(this.noteReplyContent.trim());
		},
		mailUnreadText() {
			return this.mailUnreadCount > 99 ? '99+' : String(this.mailUnreadCount);
		}
	},
	onLoad(query = {}) {
		const scene = String(query.scene || '');
		const sceneInviter = scene.split('&').reduce((result, item) => {
			const [key, value] = item.split('=');
			return key === 'inviter' ? decodeURIComponent(value || '') : result;
		}, '');
		if (query.inviter || sceneInviter) setPendingInviter(query.inviter || sceneInviter);
		this.setHeaderMetrics();
		this.loadPeopleList('recommend');
		this.loadPeopleList('hot');
	},
	onShow() {
		this.startPeopleRealtime();
		this.loadMailUnreadCount();
		this.loadDiamondBalance();
		this.openPendingWriteNote();
		this.scheduleHomeAnnouncement();
	},
	onHide() {
		this.stopPeopleRealtime();
		this.clearHomeAnnouncementTimer();
		this.homeAnnouncementVisible = false;
		if (this.writeRecording) {
			this.writeDiscardRecording = true;
			this.stopWriteRecorder();
		}
		this.clearWriteRecordTimer();
		this.releaseWriteRecorder();
		this.destroyWriteAudio();
		this.writeRecording = false;
		this.writeRecordStartAt = 0;
		this.writeRecordDuration = 0;
	},
	onUnload() {
		this.stopPeopleRealtime();
		this.clearHomeAnnouncementTimer();
		this.clearNotePickTimer();
		this.clearWriteRecordTimer();
		this.stopWriteRecorder();
		this.releaseWriteRecorder();
		this.destroyWriteAudio();
	},
	methods: {
		clearHomeAnnouncementTimer() {
			if (!this.homeAnnouncementTimer) return;
			clearTimeout(this.homeAnnouncementTimer);
			this.homeAnnouncementTimer = null;
		},
		getHomeAnnouncementDateKey() {
			const now = new Date();
			const year = now.getFullYear();
			const monthValue = now.getMonth() + 1;
			const dayValue = now.getDate();
			const month = monthValue < 10 ? `0${monthValue}` : String(monthValue);
			const day = dayValue < 10 ? `0${dayValue}` : String(dayValue);
			return `${year}-${month}-${day}`;
		},
		syncHomeAnnouncementConfig() {
			const config = getAppBootstrapConfig();
			const announcement = config && config.homeAnnouncement && typeof config.homeAnnouncement === 'object'
				? config.homeAnnouncement
				: {};
			this.homeAnnouncement = {
				enabled: Boolean(announcement.enabled),
				title: String(announcement.title || '').trim(),
				content: String(announcement.content || '').trim()
			};
		},
		async scheduleHomeAnnouncement() {
			this.clearHomeAnnouncementTimer();
			try {
				await loadAppMode();
			} catch (error) {}
			this.syncHomeAnnouncementConfig();
			if (
				!this.homeAnnouncement.enabled ||
				!this.homeAnnouncement.title ||
				!this.homeAnnouncement.content
			) {
				this.homeAnnouncementVisible = false;
				return;
			}

			const today = this.getHomeAnnouncementDateKey();
			try {
				if (uni.getStorageSync(HOME_ANNOUNCEMENT_STORAGE_KEY) === today) return;
			} catch (error) {}

			this.homeAnnouncementTimer = setTimeout(() => {
				this.homeAnnouncementTimer = null;
				if (
					this.noteOverlayVisible ||
					this.writeOverlayVisible ||
					this.softDialog.visible ||
					this.successFly.visible
				) return;
				this.homeAnnouncementVisible = true;
			}, 400);
		},
		acknowledgeHomeAnnouncement() {
			this.homeAnnouncementVisible = false;
			try {
				uni.setStorageSync(HOME_ANNOUNCEMENT_STORAGE_KEY, this.getHomeAnnouncementDateKey());
			} catch (error) {}
		},
		async loadDiamondBalance() {
			try {
				const result = await fetchDiamonds();
				this.diamondBalance = Number(result.balance || 0);
			} catch (error) {
				// The pick request still performs the authoritative balance check.
			}
		},
		clearNotePickTimer() {
			if (this.notePickTimer) {
				clearTimeout(this.notePickTimer);
				this.notePickTimer = null;
			}
		},
		setHeaderMetrics() {
			try {
				const info = uni.getSystemInfoSync();
				const rpxToPx = (info.windowWidth || 375) / 750;
				const menuButtonRect = typeof uni.getMenuButtonBoundingClientRect === 'function'
					? uni.getMenuButtonBoundingClientRect()
					: null;
				this.statusBarHeight = info.statusBarHeight || 44;
				this.menuButtonHeight = menuButtonRect && menuButtonRect.height
					? menuButtonRect.height
					: Math.round(64 * rpxToPx);
				this.searchBoxHeight = this.menuButtonHeight + Math.round(12 * rpxToPx);
				const menuButtonTop = menuButtonRect && menuButtonRect.top
					? menuButtonRect.top
					: this.statusBarHeight + Math.round(8 * rpxToPx);
				this.headerTop = Math.max(
					this.statusBarHeight,
					Math.round(menuButtonTop + (this.menuButtonHeight - this.searchBoxHeight) / 2)
				);
				this.menuButtonSafeRight = menuButtonRect && menuButtonRect.left
					? Math.max(0, info.windowWidth - menuButtonRect.left + Math.round(16 * rpxToPx))
					: Math.round(190 * rpxToPx);
			} catch (error) {
				this.statusBarHeight = 44;
				this.headerTop = 52;
				this.menuButtonHeight = 32;
				this.searchBoxHeight = 40;
				this.menuButtonSafeRight = 95;
			}
		},
		async loadMailUnreadCount() {
			try {
				const summary = await fetchNotificationSummary();
				this.mailUnreadCount = Number(summary && summary.totalUnread ? summary.totalUnread : 0);
			} catch (error) {
				this.mailUnreadCount = 0;
			}
		},
		normalizeMeetUser(user = {}, index = 0) {
			return {
				id: user.id || '',
				name: user.name || user.nickname || user.stampNo || '同频旅人',
				isMember: Boolean(user.isMember),
				avatar: user.avatar || user.avatarUrl || DEFAULT_AVATAR_URL,
				gender: user.gender || '保密',
				age: Number(user.age || 0),
				city: user.city || '未知',
				bio: user.bio || user.intro || '还没写个人介绍',
				badge: user.badge || (user.isVirtual ? '✦' : '♡'),
				match: Number(user.match || (86 - (index % 8))),
				reason: user.reason || '刚好也在这里等一次遇见',
				isVirtual: Boolean(user.isVirtual),
				online: Boolean(user.online || isChatUserOnline(user.id))
			};
		},
		getMeetPresenceUserIds() {
			return [...new Set([
				...(this.meetUsers.recommend || []),
				...(this.meetUsers.hot || [])
			].map((user) => user.id).filter(Boolean))];
		},
		subscribeMeetPresence() {
			const userIds = this.getMeetPresenceUserIds();
			if (!userIds.length) return;
			sendChatSocketEvent('presence.subscribe', { userIds });
		},
		syncMeetOnlineStates() {
			this.meetUsers = Object.keys(this.meetUsers).reduce((result, tab) => ({
				...result,
				[tab]: (this.meetUsers[tab] || []).map((user) => ({
					...user,
					online: isChatUserOnline(user.id)
				}))
			}), {});
		},
		startPeopleRealtime() {
			this.stopPeopleRealtime();
			this.realtimeUnsubscribe = subscribeChatEvents((event) => {
				if (event.type === 'ready') {
					this.subscribeMeetPresence();
					return;
				}
				if (event.type === 'presence.snapshot' || event.type === 'presence.changed') {
					this.syncMeetOnlineStates();
				}
			});
			this.subscribeMeetPresence();
		},
		stopPeopleRealtime() {
			if (!this.realtimeUnsubscribe) return;
			this.realtimeUnsubscribe();
			this.realtimeUnsubscribe = null;
		},
		async loadPeopleList(tab = this.activePeopleTab, options = {}) {
			if (!['recommend', 'hot'].includes(tab)) return;
			if (!options.silent) this.peopleLoading = true;
			try {
				const result = await fetchMeetUsers({
					tab,
					limit: 60
				});
				const items = Array.isArray(result && result.items) ? result.items : [];
				this.meetUsers = {
					...this.meetUsers,
					[tab]: items.map(this.normalizeMeetUser)
				};
				this.subscribeMeetPresence();
				this.peoplePagination = {
					...this.peoplePagination,
					[tab]: 1
				};
			} catch (error) {
				if (!options.silent) showRequestError(error, '同频用户加载失败');
			} finally {
				this.peopleLoading = false;
				if (tab === this.activePeopleTab) {
					this.peopleRefreshing = false;
				}
			}
		},
		openPendingWriteNote() {
			try {
				if (!uni.getStorageSync('meetOpenWriteNote')) return;
				uni.removeStorageSync('meetOpenWriteNote');
				setTimeout(() => {
					this.goWriteLetter();
				}, 0);
			} catch (error) {
				// Ignore storage failures; the mailbox still remains usable.
			}
		},
		async pickBottle() {
			if (this.noteOverlayVisible) return;
			if (!(await profileGuard.ensureProfileCompleted({ actionText: '收取小纸条' }))) return;
			if (this.diamondBalance < 5) {
				this.promptDiamondRecharge();
				return;
			}

			this.noteOverlayVisible = true;
			this.noteStage = 'searching';
			this.currentNote = null;
			this.noteReplyVisible = false;
			this.noteReplyContent = '';
			this.clearNotePickTimer();

			try {
				const note = await pickNote();
				this.currentNote = this.normalizePickedNote(note);
				this.diamondBalance = Number(note.diamondBalance || this.diamondBalance - 5);
			} catch (error) {
				this.closeNoteOverlay();
				if (Number(error && error.statusCode) === 402) {
					this.promptDiamondRecharge();
					return;
				}
				showRequestError(error, '小纸条捡取失败');
				return;
			}

			this.notePickTimer = setTimeout(() => {
				this.noteStage = 'opened';
				this.notePickTimer = null;
			}, 1650);
		},
		normalizePickedNote(note = {}) {
			return {
				id: note.id || '',
				authorId: note.authorId || note.userId || '',
				authorName: note.authorName || '同频旅人',
				authorIsMember: Boolean(note.authorIsMember),
				avatar: note.avatar || DEFAULT_AVATAR_URL,
				gender: note.gender || '保密',
				age: Number(note.age || 0),
				city: note.city || '未知',
				match: Number(note.match || 86),
				type: note.type || 'text',
				content: note.content || '',
				image: note.image || null,
				audio: note.audio || null,
				reason: note.reason || '都在此刻留下真实想法',
				time: note.time || '刚刚',
				replyCount: Number(note.replyCount || 0)
			};
		},
		previewPickedNoteImage() {
			if (!this.currentNote || !this.currentNote.image || !this.currentNote.image.url) return;
			uni.previewImage({ urls: [this.currentNote.image.url] });
		},
		closeNoteOverlay() {
			this.clearNotePickTimer();
			this.noteOverlayVisible = false;
			this.noteStage = 'idle';
			this.noteReplyVisible = false;
			this.noteReplyContent = '';
			this.noteReplySubmitting = false;
		},
		goNoteAuthor() {
			if (!this.currentNote || !this.currentNote.authorId) return;
			const authorId = this.currentNote.authorId;
			this.closeNoteOverlay();
			this.goUser(authorId);
		},
		toggleNoteReply() {
			if (this.noteReplySubmitting) return;
			this.noteReplyVisible = !this.noteReplyVisible;
		},
		async submitNoteReply() {
			if (!this.currentNote || !this.currentNote.id || this.noteReplySubmitting) return;
			const content = this.noteReplyContent.trim();
			if (!content) {
				this.showSoftToast('先写一句回复', 'warn');
				return;
			}
