				this.showSuccessFly('回复已送达', '对方会收到你的温暖');
				this.noteReplyContent = '';
				this.noteReplyVisible = false;
				this.currentNote = {
					...this.currentNote,
					replyCount: Number(this.currentNote.replyCount || 0) + 1
				};
			} catch (error) {
				showRequestError(error, '回复失败');
			} finally {
				this.noteReplySubmitting = false;
			}
		},
		switchPeopleTab(tab) {
			this.activePeopleTab = tab;
			this.peopleRefreshing = false;
			this.peopleLoadingMore = false;
			if (!this.currentPeopleSource.length) {
				this.loadPeopleList(tab);
			}
		},
		async refreshPeopleList() {
			if (this.peopleRefreshing) return;
			const tab = this.activePeopleTab;
			this.peopleRefreshing = true;
			this.peopleLoadingMore = false;
			await this.loadPeopleList(tab, { silent: true });
		},
		loadMorePeople() {
			if (this.peopleRefreshing || this.peopleLoadingMore || !this.peopleHasMore) return;
			const tab = this.activePeopleTab;
			const nextPage = this.currentPeoplePage + 1;
			this.peopleLoadingMore = true;

			setTimeout(() => {
				this.peoplePagination = {
					...this.peoplePagination,
					[tab]: nextPage
				};
				this.peopleLoadingMore = false;
			}, 450);
		},
		getDefaultWriteForm() {
			return {
				type: 'text',
				content: '',
				images: [],
				audio: null
			};
		},
		switchWriteType(type) {
			if (this.writeUploading || this.writeSubmitting || this.writeRecording) return;
			if (!['text', 'image', 'voice'].includes(type) || this.writeForm.type === type) return;
			this.destroyWriteAudio();
			this.writeForm = {
				...this.writeForm,
				type,
				content: type === 'text' ? this.writeForm.content : '',
				images: type === 'image' ? this.writeForm.images : [],
				audio: type === 'voice' ? this.writeForm.audio : null
			};
		},
		async goWriteLetter() {
			if (!(await profileGuard.ensureProfileCompleted({ actionText: '写小纸条' }))) return;
			this.writeOverlayVisible = true;
		},
		closeWriteOverlay(force = false) {
			const forced = force === true;
			if (!forced && (this.writeSubmitting || this.writeUploading)) return;
			this.writeDiscardRecording = true;
			this.stopWriteRecorder();
			this.destroyWriteAudio();
			this.writeOverlayVisible = false;
			this.writeRecording = false;
			this.clearWriteRecordTimer();
			this.writeVoicePlaying = false;
			this.writeVoiceLoading = false;
			this.writeForm = this.getDefaultWriteForm();
			setTimeout(() => {
				this.writeDiscardRecording = false;
			}, 0);
		},
		async chooseWriteImage() {
			if (this.writeUploading || this.writeForm.images.length >= 1) return;
			if (this.writeForm.type !== 'image') {
				this.switchWriteType('image');
			}
			try {
				const result = await uni.chooseImage({
					count: 1,
					sizeType: ['compressed', 'original'],
					sourceType: ['album', 'camera']
				});
				const files = result.tempFilePaths || [];
				if (!files.length) return;

				this.writeUploading = true;
				const filePath = files[0];
				let uploadPath = filePath;
				try {
					const compressed = await uni.compressImage({ src: filePath, quality: 82 });
					uploadPath = compressed.tempFilePath;
				} catch (error) {
					// Keep original image when compression is unavailable.
				}
				const uploaded = await uploadImage(uploadPath);
				if (uploaded && uploaded.url) {
					this.writeForm.images = [uploaded];
				}
			} catch (error) {
				if (error && error.errMsg && error.errMsg.includes('cancel')) return;
				showRequestError(error, '图片上传失败');
			} finally {
				this.writeUploading = false;
			}
		},
		removeWriteImage(index) {
			if (this.writeUploading) return;
			this.writeForm.images.splice(index, 1);
		},
		previewWriteImage(index) {
			const urls = this.writeForm.images.map((item) => item.url).filter(Boolean);
			if (!urls.length) return;
			uni.previewImage({ current: urls[index], urls });
		},
		ensureWriteRecorder() {
			if (this.writeRecorder) return this.writeRecorder;
			if (typeof uni.getRecorderManager !== 'function') {
				this.showToast('当前环境暂不支持录音');
				return null;
			}
			const recorder = uni.getRecorderManager();
			this.writeRecorderStopHandler = (result = {}) => {
				if (!this.writeRecording && !this.writeRecordStartAt) return;
				const duration = result.duration || (this.writeRecordStartAt ? Date.now() - this.writeRecordStartAt : 0);
				this.writeRecording = false;
				this.clearWriteRecordTimer();
				this.writeRecordStartAt = 0;
				this.writeRecordDuration = 0;
				if (this.writeDiscardRecording || !this.writeOverlayVisible) return;
				if (!result.tempFilePath) {
					this.showToast('没有录到声音');
					return;
				}
				this.writeForm.audio = {
					localPath: result.tempFilePath,
					duration: Math.max(1, Math.round(duration / 1000)),
					name: `voice-note-${Date.now()}.mp3`
				};
			};
			this.writeRecorderErrorHandler = (error = {}) => {
				if (!this.writeRecording) return;
				const errorMessage = String(error.errMsg || error.message || '').trim();
				this.writeRecording = false;
				this.clearWriteRecordTimer();
				this.writeRecordStartAt = 0;
				this.writeRecordDuration = 0;
				this.showToast(errorMessage ? `录音失败：${errorMessage.replace(/^.*?fail\s*/i, '')}` : '录音失败，请重试');
			};
			recorder.onStop(this.writeRecorderStopHandler);
			recorder.onError(this.writeRecorderErrorHandler);
			this.writeRecorder = recorder;
			return recorder;
		},
		releaseWriteRecorder() {
			const recorder = this.writeRecorder;
			if (recorder) {
				if (this.writeRecorderStopHandler && typeof recorder.offStop === 'function') {
					recorder.offStop(this.writeRecorderStopHandler);
				}
				if (this.writeRecorderErrorHandler && typeof recorder.offError === 'function') {
					recorder.offError(this.writeRecorderErrorHandler);
				}
			}
			this.writeRecorder = null;
			this.writeRecorderStopHandler = null;
			this.writeRecorderErrorHandler = null;
		},
		toggleWriteRecording() {
			if (this.writeSubmitting || this.writeUploading) return;
			if (this.writeForm.type !== 'voice') {
				this.switchWriteType('voice');
			}
			if (this.writeRecording) {
				this.stopWriteRecorder();
				return;
			}
			const recorder = this.ensureWriteRecorder();
			if (!recorder) return;
			this.destroyWriteAudio();
			this.writeRecordStartAt = Date.now();
			this.writeRecordDuration = 0;
			this.writeRecording = true;
			this.clearWriteRecordTimer();
			this.writeRecordTimer = setInterval(() => {
				this.writeRecordDuration = Math.min(60, Math.floor((Date.now() - this.writeRecordStartAt) / 1000));
			}, 250);
			try {
				recorder.start({
					duration: 60000,
					sampleRate: 16000,
					numberOfChannels: 1,
					encodeBitRate: 48000,
					format: 'mp3',
					frameSize: 12
				});
			} catch (error) {
				this.writeRecording = false;
				this.clearWriteRecordTimer();
				this.writeRecordStartAt = 0;
				this.writeRecordDuration = 0;
				this.showToast('录音启动失败');
			}
		},
		stopWriteRecorder() {
			if (!this.writeRecorder || !this.writeRecording) return;
			try {
				this.writeRecorder.stop();
			} catch (error) {
				this.writeRecording = false;
				this.clearWriteRecordTimer();
				this.writeRecordStartAt = 0;
				this.writeRecordDuration = 0;
			}
		},
		clearWriteRecordTimer() {
			if (this.writeRecordTimer) clearInterval(this.writeRecordTimer);
			this.writeRecordTimer = null;
		},
		playWriteVoice() {
			const audio = this.writeForm.audio;
			if (!audio || !audio.localPath) return;
			if (this.writeVoicePlaying && this.writeInnerAudio) {
				this.writeInnerAudio.stop();
				this.writeVoicePlaying = false;
				return;
			}
			this.destroyWriteAudio();
			if (typeof uni.createInnerAudioContext !== 'function') {
				this.showToast('当前环境暂不支持播放');
				return;
			}
			const player = uni.createInnerAudioContext();
			player.src = audio.localPath;
			player.onPlay(() => {
				if (this.writeInnerAudio !== player) return;
				this.writeVoiceLoading = false;
				this.writeVoicePlaying = true;
			});
			player.onEnded(() => {
				if (this.writeInnerAudio !== player) return;
				this.writeVoicePlaying = false;
				this.writeVoiceLoading = false;
			});
			player.onStop(() => {
				if (this.writeInnerAudio !== player) return;
				this.writeVoicePlaying = false;
				this.writeVoiceLoading = false;
			});
			player.onError(() => {
				if (this.writeInnerAudio !== player) return;
				this.writeVoicePlaying = false;
				this.writeVoiceLoading = false;
				this.showToast('语音播放失败');
			});
			this.writeInnerAudio = player;
			this.writeVoiceLoading = true;
			player.play();
		},
		destroyWriteAudio() {
			if (!this.writeInnerAudio) return;
			try {
				this.writeInnerAudio.stop();
				this.writeInnerAudio.destroy();
			} catch (error) {
				// Ignore cleanup failures from platform audio contexts.
			}
			this.writeInnerAudio = null;
			this.writeVoicePlaying = false;
			this.writeVoiceLoading = false;
		},
		removeWriteVoice() {
			this.destroyWriteAudio();
			this.writeForm.audio = null;
		},
		formatVoiceDuration(duration) {
			const seconds = Math.max(1, Math.round(Number(duration || 0)));
			return `${seconds}s`;
		},
		formatRecordClock(duration) {
			const seconds = Math.max(0, Math.min(60, Math.floor(Number(duration || 0))));
			return `00:${String(seconds).padStart(2, '0')}`;
		},
		getWriteTypeHint() {
			if (this.writeForm.type === 'image') {
				return this.writeForm.images.length ? '已选择图片' : '未选择图片';
			}
			if (this.writeForm.type === 'voice') {
				return this.writeForm.audio ? this.formatVoiceDuration(this.writeForm.audio.duration) : '未录音';
			}
			return `${this.writeForm.content.length} / 600`;
		},
		async buildWritePayload() {
			const type = this.writeForm.type || 'text';
			let audio = null;
			if (type === 'voice' && this.writeForm.audio && this.writeForm.audio.localPath) {
				const uploaded = await uploadAudio(this.writeForm.audio.localPath);
				audio = uploaded && uploaded.url
					? {
						url: uploaded.url,
						name: uploaded.name || this.writeForm.audio.name || '小纸条语音',
						duration: this.writeForm.audio.duration || 0
					}
					: null;
			}
			const mediaType = type === 'voice' ? 'voice' : type === 'image' ? 'image' : 'text';
			return {
				content: type === 'text' ? this.writeForm.content.trim() : '',
				type: mediaType,
				images: type === 'image' ? this.writeForm.images : [],
				audio
			};
		},
		async submitWriteNote() {
			if (this.writeSubmitting) return;
			if (this.writeUploading) {
				this.showToast('图片还在上传');
				return;
			}
			if (this.writeRecording) {
				this.showToast('先结束录音');
				return;
			}
			if (!this.canSubmitWriteNote) {
				const title = this.writeForm.type === 'image'
					? '先选择一张图片'
					: this.writeForm.type === 'voice'
						? '先录一段语音'
						: '先写下纸条内容';
				this.showToast(title);
				return;
			}
			if (!(await profileGuard.ensureProfileCompleted({ actionText: '写小纸条' }))) return;

			this.writeSubmitting = true;
			try {
				const payload = await this.buildWritePayload();
				await createNote(payload);
				this.closeWriteOverlay(true);
				this.showSuccessFly('纸条已放好', '它会漂到某个同频的人手里');
			} catch (error) {
				showRequestError(error, '纸条发布失败');
			} finally {
				this.writeSubmitting = false;
			}
		},
		goMailbox() {
			uni.navigateTo({ url: '/pages/notifications/index' });
		},
		goSearch() {
			uni.navigateTo({ url: '/pages/search/index' });
		},
		async goUser(id) {
			if (!(await profileGuard.ensureProfileCompleted({ actionText: '查看主页' }))) return;
			uni.navigateTo({ url: `/pages/user/index?id=${id}` });
		},
		goInviteFriends() {
			uni.navigateTo({ url: '/pages/invite/index' });
		},
		getGenderIcon(gender) {
			return gender === '男' ? '/static/img/nan-icon.png' : '/static/img/nv-icon.png';
		},
		showToast(title) {
			this.showSoftToast(title, 'info');
		},
		showSoftToast(message, type = 'success', duration = 1800) {
			if (this.softToastTimer) {
				clearTimeout(this.softToastTimer);
				this.softToastTimer = null;
			}
			this.softToast = { visible: true, message: String(message || ''), type };
			this.softToastTimer = setTimeout(() => {
				this.softToast = { ...this.softToast, visible: false };
				this.softToastTimer = null;
			}, duration);
		},
		showSoftDialog(options = {}) {
			const onConfirm = options.onConfirm || null;
			const onCancel = options.onCancel || null;
			this.softDialog = {
				visible: true,
				title: options.title || '',
				content: options.content || '',
				confirmText: options.confirmText || '确定',
				cancelText: options.cancelText || '取消',
				showCancel: options.showCancel !== false,
				maskClosable: options.maskClosable !== false,
				_confirm: onConfirm,
				_cancel: onCancel
			};
		},
		closeSoftDialog() {
			this.softDialog = { ...this.softDialog, visible: false };
		},
		handleSoftDialogConfirm() {
			const handler = this.softDialog._confirm;
			this.closeSoftDialog();
			if (typeof handler === 'function') handler();
		},
		handleSoftDialogCancel() {
			const handler = this.softDialog._cancel;
			this.closeSoftDialog();
			if (typeof handler === 'function') handler();
		},
		promptDiamondRecharge() {
			this.showSoftDialog({
				title: '钻石不足',
				content: '收取一张小纸条需要 5 钻石，充值后即可继续收取。',
				confirmText: '去充值',
				cancelText: '我知道了',
				maskClosable: false,
				onConfirm: () => uni.navigateTo({ url: '/pages/diamonds/index?recharge=1' })
			});
		},
		showSuccessFly(label, sublabel = '') {
			this.successFly = { visible: false, label, sublabel };
			this.$nextTick(() => {
				this.successFly = { visible: true, label, sublabel };
			});
		},
		handleSuccessFlyClose() {
			this.successFly = { ...this.successFly, visible: false };
		}
	}
};
</script>

