	0% {
		transform: translate3d(-230rpx, -50%, 0) rotate(-18deg) scaleX(0.64);
		opacity: 0;
	}
	16% {
		opacity: 0.95;
	}
	62% {
		opacity: 0.92;
	}
	100% {
		transform: translate3d(230rpx, -50%, 0) rotate(-18deg) scaleX(1.04);
		opacity: 0;
	}
}

