	0% {
		transform: translate3d(230rpx, -50%, 0) rotate(16deg) scaleX(0.68);
		opacity: 0;
	}
	18% {
		opacity: 0.86;
	}
	64% {
		opacity: 0.82;
	}
	100% {
		transform: translate3d(-230rpx, -50%, 0) rotate(16deg) scaleX(1);
		opacity: 0;
	}
}

