	width: 172rpx;
	height: 172rpx;
	background: radial-gradient(circle, rgba(255, 236, 245, 0.9) 0%, rgba(255, 246, 250, 0.55) 36%, rgba(255, 255, 255, 0) 72%);
}

.light-beam-loader::after {
	width: 230rpx;
	height: 116rpx;
	background: radial-gradient(ellipse, rgba(143, 112, 210, 0.12) 0%, rgba(255, 255, 255, 0) 70%);
}

.beam {
	position: absolute;
	left: 50%;
	top: 50%;
	width: 228rpx;
	height: 8rpx;
	border-radius: 999rpx;
	opacity: 0;
	transform-origin: 50% 50%;
	z-index: 2;
}

.beam::before {
	content: '';
	position: absolute;
	inset: -8rpx -18rpx;
	border-radius: inherit;
	background: inherit;
	filter: blur(12rpx);
	opacity: 0.5;
}

.beam-pink {
	top: 42%;
	height: 8rpx;
	background: linear-gradient(90deg, rgba(255, 139, 167, 0), rgba(255, 139, 167, 0.88) 28%, #ffffff 50%, rgba(255, 103, 145, 0.72) 72%, rgba(255, 103, 145, 0));
	box-shadow: 0 0 18rpx rgba(255, 139, 167, 0.58);
}

.beam-purple {
	top: 52%;
	width: 210rpx;
	height: 7rpx;
	background: linear-gradient(90deg, rgba(143, 112, 210, 0), rgba(143, 112, 210, 0.8) 30%, #ffffff 52%, rgba(143, 112, 210, 0.6) 76%, rgba(143, 112, 210, 0));
	box-shadow: 0 0 16rpx rgba(143, 112, 210, 0.48);
}

.beam-rose {
	top: 60%;
	width: 178rpx;
	height: 6rpx;
	background: linear-gradient(90deg, rgba(238, 90, 138, 0), rgba(238, 90, 138, 0.74) 32%, #fff6fb 50%, rgba(212, 104, 138, 0.52) 74%, rgba(212, 104, 138, 0));
	box-shadow: 0 0 14rpx rgba(238, 90, 138, 0.42);
}

.beam-blue {
	top: 48%;
	width: 198rpx;
	height: 6rpx;
	background: linear-gradient(90deg, rgba(99, 181, 218, 0), rgba(99, 181, 218, 0.5) 30%, #ffffff 52%, rgba(139, 116, 224, 0.54) 74%, rgba(139, 116, 224, 0));
	box-shadow: 0 0 14rpx rgba(99, 181, 218, 0.34);
}

.beam-fast {
	animation: beamTravel 1.12s cubic-bezier(0.22, 0.74, 0.28, 1) infinite;
}

.beam-medium {
	animation: beamTravel 1.42s 0.18s cubic-bezier(0.22, 0.74, 0.28, 1) infinite;
}

.beam-slow {
	animation: beamTravel 1.74s 0.42s cubic-bezier(0.22, 0.74, 0.28, 1) infinite;
}

.beam-reverse {
	animation: beamTravelReverse 1.36s 0.34s cubic-bezier(0.22, 0.74, 0.28, 1) infinite;
}

.beam-spark {
	position: absolute;
	left: 50%;
	top: 50%;
	width: 14rpx;
	height: 14rpx;
	border-radius: 50%;
	background: radial-gradient(circle, #ffffff 0%, #ffb4ca 58%, rgba(212, 104, 138, 0) 100%);
	box-shadow: 0 0 18rpx rgba(255, 139, 167, 0.76);
	opacity: 0;
	z-index: 4;
	animation: beamSparkDrift 1.55s ease-in-out infinite;
}

.spark-right {
	width: 10rpx;
	height: 10rpx;
	background: radial-gradient(circle, #ffffff 0%, #bba2f0 58%, rgba(143, 112, 210, 0) 100%);
	box-shadow: 0 0 16rpx rgba(143, 112, 210, 0.68);
	animation-delay: 0.46s;
	animation-direction: reverse;
}

.beam-core {
	position: relative;
	width: 42rpx;
	height: 42rpx;
	border-radius: 50%;
	background: radial-gradient(circle, #ffffff 0%, #ffe6f0 45%, rgba(212, 104, 138, 0.25) 100%);
	box-shadow:
		0 0 24rpx rgba(212, 104, 138, 0.56),
		0 0 42rpx rgba(143, 112, 210, 0.24),
		inset 0 0 8rpx rgba(255, 255, 255, 0.95);
	animation: beamCorePulse 1.45s ease-in-out infinite;
	z-index: 5;
}

.beam-core::after {
	content: '';
	position: absolute;
	top: 50%;
	left: 50%;
	width: 12rpx;
	height: 12rpx;
	border-radius: 50%;
	background: linear-gradient(135deg, #d4688a, #8f70d2);
	transform: translate(-50%, -50%);
	box-shadow: 0 0 12rpx rgba(212, 104, 138, 0.72);
}

.loading-dots {
